<?php

/* @autogenerated */
declare(strict_types=1);

namespace Civi\Lughauth\Features\Document\SnippetAsset\Domain\ValueObject\Accessor;

use Civi\Lughauth\Features\Document\SnippetAsset\Domain\ValueObject\SnippetAssetTypeVO;

trait SnippetAssetTypeAccessor
{
    private SnippetAssetTypeVO $_type;
    public function getType(): string
    {
        return $this->_type->value();
    }
    public function type(): SnippetAssetTypeVO
    {
        return $this->_type;
    }
    public function isTypeChanged(?self $original = null): bool
    {
        return !$this->_type->equals($original?->_type);
    }
    public function withType(SnippetAssetTypeVO|string $type): self
    {
        $copy = clone $this;
        $copy->_type = SnippetAssetTypeVO::from($type);
        return $copy;
    }
}
